package dev.practice.shopapp;

import dev.practice.shopapp.enums.AddressType;
import dev.practice.shopapp.models.Address;
import dev.practice.shopapp.models.Product;
import dev.practice.shopapp.models.User;
import dev.practice.shopapp.repositories.ProductRepository;
import dev.practice.shopapp.repositories.UserRepository;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.math.BigDecimal;
import java.util.Map;

@Configuration
public class DataSeeder {

    @Bean
    CommandLineRunner initDatabase(UserRepository userRepository, ProductRepository productRepository) {
        return args -> {

            if (userRepository.count() == 0) {
                // 1. Create Alex Developer
                User alex = new User();
                alex.setFirstName("Alex");
                alex.setLastName("Developer");
                alex.setEmail("alex.test@docker.local");
                alex.setPhoneNumber("+12345678901");

                Address home = new Address();
                home.setStreetAddress("123 Java Lane");
                home.setCity("Springfield");
                home.setCountryCode("US");
                home.setPostalCode("62704");
                home.setAddressType(AddressType.PRIMARY);

                alex.addAddress(home);
                userRepository.save(alex);

                // 2. Create Sarah Tester
                User sarah = new User();
                sarah.setFirstName("Sarah");
                sarah.setLastName("Tester");
                sarah.setEmail("sarah.tester@docker.local");
                sarah.setPhoneNumber("+19876543210");

                Address work = new Address();
                work.setStreetAddress("789 Pine Lane");
                work.setCity("Seattle");
                work.setCountryCode("US");
                work.setPostalCode("98101");
                work.setAddressType(AddressType.PRIMARY);

                sarah.addAddress(work);
                userRepository.save(sarah);

                System.out.println("✅ Local Docker database successfully seeded with test users!");
            }

            // --- 2. SEED PRODUCTS (Veloce Forge Catalog) ---
            if (productRepository.count() == 0) {

                // --- BASE64 PLACEHOLDERS (Replace these with your actual long strings) ---
                String imgKeyboard = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8/5+hHgAHggJ/PchI7wAAAABJRU5ErkJggg==";
                String imgMouse = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADegG7PZ9B6AAAAABJRU5ErkJggg==";
                String imgAudio = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8/5+hHgAHggJ/PchI7wAAAABJRU5ErkJggg==";
                String imgDeskMat = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwADPQG+e/I0OAAAAABJRU5ErkJggg==";

                // 1. THE LINEAR MASTERPIECE
                Product kb60 = Product.builder()
                        .sku("VF-KB-60L").name("Linear-60 Mechanical Board").category("Keyboards")
                        .manufacturer("Veloce Forge").price(new BigDecimal("189.99")).costPrice(new BigDecimal("110.00"))
                        .currencyCode("USD").lowStockThreshold(10).imageUrl(KEYBOARD).createdBy("system")
                        .attributes(Map.of("switch", "Veloce Red Linear", "layout", "60%", "hotswap", "Yes")).build();
                kb60.updateStock(45);
                productRepository.save(kb60);

                // 2. THE TACTILE PRO (Low Stock Case)
                Product kb75 = Product.builder()
                        .sku("VF-KB-75T").name("Tactile-75 Pro Edition").category("Keyboards")
                        .manufacturer("Veloce Forge").price(new BigDecimal("219.99")).costPrice(new BigDecimal("135.00"))
                        .currencyCode("USD").lowStockThreshold(15).imageUrl(IMG_CONTROLLER).createdBy("system")
                        .attributes(Map.of("switch", "Veloce Brown Tactile", "layout", "75%", "rgb", "Per-key")).build();
                kb75.updateStock(8); // Triggers Amber Alert
                productRepository.save(kb75);

                // 3. THE RAPTOR MOUSE
                Product mouseApx = Product.builder()
                        .sku("VF-MS-APX").name("Apex-Pro Optical Mouse").category("Mice")
                        .manufacturer("Veloce Forge").price(new BigDecimal("79.99")).costPrice(new BigDecimal("40.00"))
                        .currencyCode("USD").lowStockThreshold(20).imageUrl(MOUSE).createdBy("system")
                        .attributes(Map.of("sensor", "26k DPI Optical", "polling", "8kHz", "weight", "62g")).build();
                mouseApx.updateStock(120);
                productRepository.save(mouseApx);

                // 4. THE ERGO ZEALOT
                Product mouseZlt = Product.builder()
                        .sku("VF-MS-ZLT").name("Zealot Vertical Ergo").category("Mice")
                        .manufacturer("Veloce Forge").price(new BigDecimal("89.99")).costPrice(new BigDecimal("45.00"))
                        .currencyCode("USD").lowStockThreshold(10).imageUrl(KEYBOARD_2).createdBy("system")
                        .attributes(Map.of("sensor", "Precision Laser", "ergonomic", "Vertical 57°")).build();
                mouseZlt.updateStock(52);
                productRepository.save(mouseZlt);

                // 5. THE SONIC FORGE (Out of Stock Case)
                Product headset = Product.builder()
                        .sku("VF-AU-SNK").name("Sonic-Forge Wireless").category("Audio")
                        .manufacturer("Veloce Forge").price(new BigDecimal("159.99")).costPrice(new BigDecimal("90.00"))
                        .currencyCode("USD").lowStockThreshold(5).imageUrl(OPTIACAL_MOUSE).createdBy("system")
                        .attributes(Map.of("driver", "50mm Neodymium", "battery", "40h", "latency", "Low-latency 2.4G")).build();
                headset.updateStock(0); // Triggers Red Alert
                productRepository.save(headset);

                // 6. THE AURA DESK MAT
                Product mat = Product.builder()
                        .sku("VF-DM-AUR").name("Aura RGB Desk Mat").category("Desk Aesthetics")
                        .manufacturer("Veloce Forge").price(new BigDecimal("49.99")).costPrice(new BigDecimal("20.00"))
                        .currencyCode("USD").lowStockThreshold(50).imageUrl(IMG_MOUSEPAD).createdBy("system")
                        .attributes(Map.of("size", "900x400mm", "material", "Micro-weave", "led", "Addressable RGB")).build();
                mat.updateStock(250);
                productRepository.save(mat);

                System.out.println("✅ Veloce Forge catalog (6 items) successfully seeded!");
            }
        };
    }
    private static final String KEYBOARD = "data:image/jpeg;base64,";
    private static final String MOUSE = "data:image/jpeg;base64,";
    private static final String IMG_MOUSEPAD = "data:image/jpeg;base64,";
    private static final String IMG_CONTROLLER = "data:image/jpeg;base64,";
    private static final String OPTIACAL_MOUSE = "data:image/jpeg;base64,";
    private static final String KEYBOARD_2 = "data:image/jpeg;base64,";

}
